<script type="application/ld+json"><?=json_encode(['@context'=>'https://schema.org','@type'=>'BreadcrumbList','itemListElement'=>[['@type'=>'ListItem','position'=>1,'name'=>'돈시간','item'=>'https://dontime.kr/'],['@type'=>'ListItem','position'=>2,'name'=>$category],['@type'=>'ListItem','position'=>3,'name'=>$name.' 계산기','item'=>$canonical]]],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?></script>
